from pathlib import Path
import json,html,re,zipfile
from html.parser import HTMLParser
R=Path(__file__).parent;E=R/'extraction'
m=json.loads((E/'manifest.json').read_text());products=json.loads((E/'products.json').read_text())['products'];assets=json.loads((E/'assets.json').read_text())
class Text(HTMLParser):
 def __init__(self):super().__init__();self.out=[]
 def handle_starttag(self,t,a):
  if t in ['p','div','h1','h2','h3','h4','li','br','section']:self.out.append('\n')
 def handle_data(self,d):self.out.append(d)
def clean(s):
 p=Text();p.feed(s);return re.sub(r'\n\s*\n+','\n',''.join(p.out)).strip()
for r in m:
 p=E/r['file'].replace('.html','.main.html')
 if p.exists():
  text=clean(p.read_text());(E/r['file'].replace('.html','.content.txt')).write_text(text);r['content_file']=r['file'].replace('.html','.content.txt')
(E/'manifest.json').write_text(json.dumps(m,indent=2))
issues=[
 ('Payment terms conflict','The Plug-In Plan’s checkout product is $100, but its copy says a $99 deposit, $300 balance, and $399 total. The package collection also displays $400. Confirm the actual deposit, total, balance due date, and conditions before enabling the deposit purchase option. The draft sends visitors to a consultation for this plan.'),
 ('Product links conflict with labels','The old homepage’s Mock Technical Interview link goes to the product now titled The Plug-In Plan. A 30-Day Tech Interview feature links to the $20 Technical Interview Preparation product. The redesign routes these services by actual catalog content.'),
 ('All testimonial author labels conflict','The first account identifies itself as Tolu but its author label is Zeke. The second identifies Wale but is labeled Terry. The third describes Wale but is labeled Thomas. The redesign uses one short anonymized quote and source-grounded summaries; confirm names, permission, employers, dates, and outcomes before adding named case studies.'),
 ('Unsubstantiated counters and logos','The original homepage source contains 13 hiring partners, 25 technologies, 1K placements, and 2K applications, but the counter text does not reliably render. Company logos are presented under a combined interviews-and-jobs claim. These figures and implied company affiliations are not independently supported by the pages and are omitted from the draft.'),
 ('Intake copy is stale','The old intake page promises fewer than two minutes and four quick questions. The live linked form is a longer career onboarding form; its current introduction says about 10 minutes. The draft avoids the shorter promise and preserves the actual Google Form.'),
 ('Unrelated template content','The old intake page includes music-themed filler, Latin placeholder text, and a generic team roster. This content is archived and removed from the redesign.'),
 ('Consultation duration','The Calendly URL ends in /30min, but the live event is titled 15 Minute Consultation and displays 15 min. The draft follows the live event.'),
 ('Template errors','The old footer includes a Liquid image-width error, and testimonial CSS contains invalid mask-image Liquid URLs. The new theme passes Shopify Theme Check without offenses.'),
 ('Deployment and integration verification','The current CLI identity cannot access 0mdj10-0h.myshopify.com. No live theme, products, orders, form settings, or responses were changed. The Google Form and Calendly both load at their direct URLs; the Google embed also loads on the existing public store. Their frames remain blank in the local browser preview. Repeat embedded checks on an unpublished Shopify theme and verify a test response in the owner’s Google Forms Responses tab before launch. No test response or appointment was submitted.'),
 ('Public extraction scope','This is a crawl of all discovered public sitemap and linked content pages, public catalog JSON, and 38 referenced images. It is not an export of private orders, customers, theme source, installed apps, hidden products, or original paid-theme code. CSS/script dependencies of the original theme are referenced in the archived HTML, not exhaustively mirrored.')]
rows=''.join('<tr><td><a href="https://www.jobplug.co/products/'+p['handle']+'">'+html.escape(p['title'])+'</a></td><td>'+html.escape('; '.join(v['title']+': $'+v['price'] for v in p['variants']))+'</td><td>'+html.escape(clean(p['body_html']))+'</td></tr>' for p in products)
page_rows=''.join('<tr><td><a href="'+r['url']+'">'+r['url']+'</a></td><td>'+str(r.get('status','ERROR'))+'</td><td><a href="extraction/'+r['file']+'">HTML snapshot</a>'+(' · <a href="extraction/'+r['content_file']+'">Clean content</a>' if r.get('content_file') else '')+'</td></tr>' for r in m)
body='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JobPlug — content extraction and redesign review</title><style>body{font:15px/1.65 system-ui,sans-serif;color:#182727;background:#f9faf5;margin:0}main{max-width:1120px;margin:auto;padding:50px 30px}h1{font-size:46px;line-height:1.1;letter-spacing:-2px}h2{margin-top:50px;font-size:28px}h3{font-size:18px}a{color:#3357db}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid #dce1d8;text-align:left;padding:16px;vertical-align:top}td:first-child{min-width:190px;overflow-wrap:anywhere}td:last-child{max-width:620px}article{background:white;border:1px solid #dce1d8;padding:22px 28px;border-radius:12px;margin:16px 0}details{padding:18px 0;border-bottom:1px solid #dce1d8}summary{font-weight:600;cursor:pointer}pre{white-space:pre-wrap;font:13px/1.6 system-ui}code{background:#e9eee5;padding:3px 6px}.pill{display:inline-block;background:#dafa8b;padding:8px 14px;margin:8px 8px 8px 0;border-radius:30px}.muted{color:#596560}.table-scroll{overflow:auto}</style></head><body><main><p class="muted">JOBPLUG / WEBSITE REVAMP / OCTOBER 3, 2026</p><h1>One business. A clearer story.</h1><p>A complete public-content extraction and Shopify redesign, with existing booking and intake destinations preserved.</p><span class="pill">28 public URLs</span><span class="pill">12 products</span><span class="pill">38 image assets</span><span class="pill">27 preview pages</span><p><a href="http://localhost:8765/">Open website preview</a> · <a href="jobplug-shopify-theme.zip">Shopify theme ZIP</a> · <a href="extraction/manifest.json">Source manifest</a></p><h2>Design and client journey</h2><p>The redesign keeps the brand’s blue and introduces warm neutral backgrounds, consistent typography, clear service categories, and visible booking/intake actions. The journey is: understand the support → choose a service or package → book a consultation or complete intake → purchase through Shopify → follow onboarding.</p><p>Navigation: Services, Packages, Success stories, Our story, Book a consultation. The footer adds career resources, intake, contact, and cart. Existing product, collection, page, and blog paths are preserved. Google Forms handles intake submissions directly; the theme does not intercept answers or write to an imitation form endpoint.</p><h2>What is ready</h2><ul><li>Native Shopify Online Store 2.0 theme: homepage sections, product, collection, page, blog, article, cart, search, 404, and app-block support.</li><li>Existing Shopify prices are read dynamically in the theme. Preview prices are the captured catalog snapshot.</li><li>Responsive service filters, mobile menu, accessible focus states, skip link, FAQs, and native product/contact forms.</li><li>Calendly and Google Form URLs are editable in Theme settings → Booking and intake.</li><li>Raw HTML, clean main content, product/collection JSON, sitemap files, and downloaded image assets are retained.</li></ul><h2>Review before launch</h2>'''
body+=''.join('<article><h3>'+a+'</h3><p>'+b+'</p></article>' for a,b in issues)
body+='<h2>All services and packages</h2><p>Amounts below are a captured snapshot. Detailed descriptions are extracted from the public product catalog.</p><div class="table-scroll"><table><thead><tr><th>Product</th><th>Checkout variants</th><th>Published scope</th></tr></thead><tbody>'+rows+'</tbody></table></div><h2>Public URL inventory</h2><div class="table-scroll"><table><thead><tr><th>Source URL</th><th>Status</th><th>Saved extraction</th></tr></thead><tbody>'+page_rows+'</tbody></table></div><h2>Extracted page content</h2>'
for r in m:
 if r.get('content_file'):body+='<details><summary>'+html.escape(r['url'])+'</summary><pre>'+html.escape((E/r['content_file']).read_text())+'</pre></details>'
body+='</main></body></html>'; (R/'extraction-report.html').write_text(body)
with zipfile.ZipFile(R/'jobplug-public-extraction.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in E.rglob('*'):
  if f.is_file():z.write(f,'extraction/'+str(f.relative_to(E)))
 z.write(R/'extraction-report.html','extraction-report.html')
print('Wrote extraction report and complete public archive.')
